"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/goal.css";
import type { HTMLAttributes, ReactNode } from "react";
import { formatAnalyticsValue } from "../../lib/analytics";
import { cn } from "../../lib/cn";

export type GoalProps = Omit<HTMLAttributes<HTMLDivElement>, "title"> & {
  label: string;
  value: number;
  target: number;
  formatter?: (value: number) => string;
  description?: ReactNode;
};

export function Goal({ label, value, target, formatter = formatAnalyticsValue, description, className, ...props }: GoalProps) {
  const ratio = target > 0 ? Math.max(0, value / target) : 0;
  const progress = Math.min(1, ratio);
  const goalStyle = { "--whatiuse-goal-progress": progress } as React.CSSProperties;
  return (
    <div className={cn("whatiuse-goal", className)} style={goalStyle} {...props}>
      <div className="whatiuse-goal__heading"><span>{label}</span><strong>{Math.round(ratio * 100)}%</strong></div>
      <div className="whatiuse-goal__track" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={target} aria-valuenow={Math.min(target, Math.max(0, value))} aria-valuetext={`${formatter(value)} of ${formatter(target)}`}>
        <span className="whatiuse-goal__indicator" />
      </div>
      <div className="whatiuse-goal__meta"><span>{formatter(value)}</span><span>Target {formatter(target)}</span></div>
      {description && <div className="whatiuse-goal__description">{description}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-goal { display: grid; min-width: 0; gap: 8px; }

.whatiuse-goal__heading,
.whatiuse-goal__meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; }

.whatiuse-goal__heading { color: var(--whatiuse-fg-default); font-size: var(--whatiuse-type-ui); }

.whatiuse-goal__heading strong { font-variant-numeric: tabular-nums; font-weight: 590; }

.whatiuse-goal__track { height: 5px; overflow: hidden; border-radius: 999px; background: var(--whatiuse-bg-subtle); }

.whatiuse-goal__indicator { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--whatiuse-fg-default); transform: scaleX(var(--whatiuse-goal-progress)); transform-origin: left center; transition: transform var(--whatiuse-medium) var(--whatiuse-ease-out); }

.whatiuse-goal__meta { color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); font-variant-numeric: tabular-nums; }

.whatiuse-goal__description { color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-metadata); line-height: 1.45; }

@media (prefers-reduced-motion: reduce) {
.whatiuse-goal__indicator { transition-duration: 0ms; }
}
}
